public enum Xkh73Type {


    TRADE(Xzv64.SHOPPING, "거래 관련 알림"),
    BID(Xzv64.SHOPPING, "입찰 관련 알림"),
    STORAGE(Xzv64.SHOPPING, "보관 관련 알림"),
    FAVORITE(Xzv64.SHOPPING, "관심 상품 관련 알림"),
    BENEFIT(Xzv64.SHOPPING, "혜택 관련 알림"),
    ANNOUNCEMENT(Xzv64.SHOPPING, "공지사항 알림"),
    REFUND(Xzv64.SHOPPING, "환불 관련 알림"),


    LIKE(Xzv64.STYLE, "좋아요 관련 알림"),
    COMMENT(Xzv64.STYLE, "댓글 관련 알림"),
    FOLLOW(Xzv64.STYLE, "팔로우 관련 알림");

    private final Xzv64 category;
    private final String description;

    Xkh73Type(Xzv64 category, String description) {
        this.category = category;
        this.description = description;
    }

    public Xzv64 getCategory() {
        return category;
    }

    public String getDescription() {
        return description;
    }







    public static Xkh73Type[] getTypesByCategory(Xzv64 category) {
        if (category == null) {
            return values();
        }

        return java.util.Arrays.stream(values())
                .filter(type -> type.getCategory() == category)
                .toArray(Xkh73Type[]::new);
    }
