package com.fream.back.domain.m02.entity;

import com.fream.back.global.entity.Xwb79Entity;
import jakarta.persistence.*;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Getter;
import lombok.NoArgsConstructor;

import java.util.ArrayList;
import java.util.List;

@Entity
@Table(name = "product_color", indexes = {
        @Index(name = "idx_product_color_name", columnList = "color_name"),
        @Index(name = "idx_product_color_product", columnList = "product_id")
})
@Getter
@NoArgsConstructor
@AllArgsConstructor
@Builder
public class Xfp92 extends Xwb79Entity {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(nullable = false)
    private String colorName;

    @Lob
    private String content;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "product_id")
    private Xkr46 product;

    @OneToOne(cascade = CascadeType.ALL, orphanRemoval = true)
    @JoinColumn(name = "thumbnail_image_id", nullable = true)
    private Xzq99 thumbnailImage;

    @Builder.Default
    @OneToMany(mappedBy = "productColor", cascade = CascadeType.ALL, orphanRemoval = true)
    private List<Xdh20> sizes = new ArrayList<>();

    @Builder.Default
    @OneToMany(mappedBy = "productColor", cascade = CascadeType.ALL, orphanRemoval = true)
    private List<Xzq99> productImages = new ArrayList<>();

    @Builder.Default
    @OneToMany(mappedBy = "productColor", cascade = CascadeType.ALL, orphanRemoval = true)
    private List<Xkj24> productDetailImages = new ArrayList<>();

    @Builder.Default
    @OneToMany(mappedBy = "productColor", cascade = CascadeType.ALL, orphanRemoval = true)
    private List<Xrf21> interests = new ArrayList<>();


    public void assignProduct(Xkr46 product) {
        this.product = product;
    }

    public void addThumbnailImage(Xzq99 thumbnailImage) {
        this.thumbnailImage = thumbnailImage;
        if (thumbnailImage != null) {
            thumbnailImage.assignProductColor(this);
        }
    }

    public void addProductImage(Xzq99 image) {
        productImages.add(image);
        image.assignProductColor(this);
    }

    public void addProductDetailImage(Xkj24 detailImage) {
        productDetailImages.add(detailImage);
        detailImage.assignProductColor(this);
    }

    public void addProductSize(Xdh20 size) {
        sizes.add(size);
        size.assignProductColor(this);
    }

    public void update(String colorName, String content) {
        this.colorName = colorName;
        this.content = content;
    }


}

