    private BooleanExpression buildPricePredicate(Integer minPrice, Integer maxPrice, QXdh20 productSize) {
        BooleanExpression predicate = null;
        if (minPrice != null) {
            predicate = productSize.purchasePrice.goe(minPrice);
        }
        if (maxPrice != null) {
            predicate = predicate == null ? productSize.purchasePrice.loe(maxPrice) : predicate.and(productSize.purchasePrice.loe(maxPrice));
        }
        return predicate;
    }

